#!/usr/bin/env python3
from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
HELPER = ROOT / "scripts/ci/capture_accepted_build_input_snapshot.py"
TEST = ROOT / "scripts/ci/tests/test_capture_generated_shared_ancestor_continuity.py"

helper = HELPER.read_text(encoding="utf-8")
old_helper = '''            child = _open_directory_at(current, component, relative)\n            held: int | None = None\n            try:\n                if not is_last and directory_cache is not None:\n                    held = os.dup(child)\n                    admitted = os.fstat(held)\n                    directory_cache[relative] = (held, admitted)\n                    held = None\n'''
new_helper = '''            child = _open_directory_at(current, component, relative)\n            held: int | None = None\n            try:\n                if directory_cache is not None:\n                    parent_relative = relative.parent\n                    cached_parent = directory_cache.get(parent_relative)\n                    if cached_parent is not None:\n                        parent_descriptor, parent_admitted = cached_parent\n                        _assert_directory_generation(\n                            parent_descriptor,\n                            parent_admitted,\n                            parent_relative,\n                        )\n                if not is_last and directory_cache is not None:\n                    held = os.dup(child)\n                    admitted = os.fstat(held)\n                    directory_cache[relative] = (held, admitted)\n                    held = None\n'''
if helper.count(old_helper) != 1:
    raise SystemExit("helper anchor did not match exactly once")
HELPER.write_text(helper.replace(old_helper, new_helper, 1), encoding="utf-8")

test = TEST.read_text(encoding="utf-8")
anchor = '''    def test_cache_dup_failure_closes_newly_opened_child_descriptor(self) -> None:\n'''
if test.count(anchor) != 1:
    raise SystemExit("test insertion anchor did not match exactly once")
insert = '''    def test_manifest_rejects_final_child_replacement_after_parent_revalidation(self) -> None:\n        helper = load()\n        with tempfile.TemporaryDirectory(prefix="nembra-final-child-manifest-") as raw:\n            root = Path(raw)\n            seed_common(root)\n            generation_a = make_generation(root, "LocalSecrets.A", b"SDK-A\\n", b"RUNTIME-A\\n")\n            generation_b = make_generation(root, "LocalSecrets.B", b"SDK-B\\n", b"RUNTIME-B\\n")\n            generation_a.rename(root / "LocalSecrets")\n            original_open = helper._open_directory_at\n            swapped = False\n\n            def splice_after_parent_check(parent_fd: int, name: str, relative: Path):\n                nonlocal swapped\n                if relative == Path("LocalSecrets/TuyaRuntime") and not swapped:\n                    active = root / "LocalSecrets"\n                    (active / "TuyaRuntime").rename(active / "TuyaRuntime.A.attack")\n                    (generation_b / "TuyaRuntime").rename(active / "TuyaRuntime")\n                    swapped = True\n                return original_open(parent_fd, name, relative)\n\n            with mock.patch.object(helper, "_open_directory_at", side_effect=splice_after_parent_check):\n                with self.assertRaises(helper.AcceptedBuildInputSnapshotError):\n                    helper.canonical_generated_manifest(root, SOURCE_SHA)\n\n            self.assertTrue(swapped, "attack hook never reached final Runtime child open")\n\n    def test_copy_rejects_final_child_replacement_after_parent_revalidation(self) -> None:\n        helper = load()\n        with tempfile.TemporaryDirectory(prefix="nembra-final-child-copy-") as raw:\n            root = Path(raw)\n            seed_common(root)\n            generation_a = make_generation(root, "LocalSecrets.A", b"SDK-A\\n", b"RUNTIME-A\\n")\n            generation_b = make_generation(root, "LocalSecrets.B", b"SDK-B\\n", b"RUNTIME-B\\n")\n            generation_a.rename(root / "LocalSecrets")\n            destination = root / "stage"\n            destination.mkdir()\n            original_open = helper._open_directory_at\n            swapped = False\n\n            def splice_after_parent_check(parent_fd: int, name: str, relative: Path):\n                nonlocal swapped\n                if relative == Path("LocalSecrets/TuyaRuntime") and not swapped:\n                    active = root / "LocalSecrets"\n                    (active / "TuyaRuntime").rename(active / "TuyaRuntime.A.attack")\n                    (generation_b / "TuyaRuntime").rename(active / "TuyaRuntime")\n                    swapped = True\n                return original_open(parent_fd, name, relative)\n\n            with mock.patch.object(helper, "_open_directory_at", side_effect=splice_after_parent_check):\n                with self.assertRaises(helper.AcceptedBuildInputSnapshotError):\n                    helper._copy_generated_subjects(root, destination)\n\n            self.assertTrue(swapped, "attack hook never reached final Runtime child open")\n            runtime = destination / "LocalSecrets/TuyaRuntime/identity.bin"\n            if runtime.exists():\n                self.assertNotEqual(runtime.read_bytes(), b"RUNTIME-B\\n")\n\n'''
TEST.write_text(test.replace(anchor, insert + anchor, 1), encoding="utf-8")
